use anyhow::Result;
use std::collections::HashMap;
use std::fmt::Write;

use super::Rendered;
use super::shell::{export, quote};

use crate::config::model::Env;
use crate::config::resolve::{Derived, Resolved};

/// Render `TF_VAR_*` exports for Terraform, plus the `AWS_*` credentials the S3
/// remote-state backend reads at init time.
///
/// Non-secret infra config lives in `environments/*.tfvars` and our own secrets
/// are generated by Terraform, so neither is emitted here.
pub fn render(r: &Resolved, env: Env) -> Result<Rendered> {
    let derived = Derived::load();
    let mut out = String::new();

    let provider_keys = provider_api_keys(r, env);

    // A placeholder is dropped from the map, which would otherwise deploy a
    // partially configured provider set without saying so.
    let warnings: Vec<String> = r
        .secrets
        .placeholders_matching("PROVIDER_", &format!("_API_KEY_{}", env.suffix()))
        .into_iter()
        .map(|key| format!("{key} is still a placeholder — that provider will not be deployed"))
        .collect();

    export(&mut out, "TF_VAR_scw_secret_key", &derived.scw_secret_key);
    export(&mut out, "TF_VAR_image_tag", &derived.image_tag);
    export(
        &mut out,
        "TF_VAR_staan_api_key",
        r.secrets.optional_env("STAAN_API_KEY", env),
    );
    // Optional previous keys, accepted only during a rotation.
    export(
        &mut out,
        "TF_VAR_eigin_relay_secondary_key",
        r.secrets.optional_env("EIGIN_RELAY_SECONDARY_KEY", env),
    );
    export(
        &mut out,
        "TF_VAR_token_encryption_secondary_key",
        r.secrets
            .optional_env("TOKEN_ENCRYPTION_SECONDARY_KEY", env),
    );
    let _ = writeln!(
        out,
        "export TF_VAR_provider_api_keys={}",
        quote(&serde_json::to_string(&provider_keys)?)
    );
    export(
        &mut out,
        "TF_VAR_alerts_email",
        &r.config.app.contact.alerts,
    );

    let (access, secret, region) = backend_creds(r, &derived);
    export(&mut out, "AWS_ACCESS_KEY_ID", &access);
    export(&mut out, "AWS_SECRET_ACCESS_KEY", &secret);
    export(&mut out, "AWS_DEFAULT_REGION", &region);

    Ok(Rendered::new(out, warnings))
}

/// Every `PROVIDER_<NAME>_API_KEY_<ENV>` becomes `<name>` (lowercased) → key.
fn provider_api_keys(r: &Resolved, env: Env) -> HashMap<String, String> {
    r.secrets
        .matching("PROVIDER_", &format!("_API_KEY_{}", env.suffix()))
        .into_iter()
        .map(|(name, value)| (name.to_lowercase(), value))
        .collect()
}

/// Whether Terraform has everything it needs to authenticate.
///
/// Checks the resolved credentials rather than the presence of any one variable:
/// each field falls back to the scw CLI, so `TFSTATE_*` being unset proves nothing.
pub fn credentials_ready(r: &Resolved) -> bool {
    let derived = Derived::load();
    let (access, secret, _) = backend_creds(r, &derived);
    !access.is_empty() && !secret.is_empty() && !derived.scw_secret_key.is_empty()
}

/// The scoped state key from `.env` wins; the scw CLI config is the per-field fallback.
fn backend_creds(r: &Resolved, derived: &Derived) -> (String, String, String) {
    let pick = |key: &str, fallback: &str| {
        let value = r.secrets.optional(key);
        if value.is_empty() {
            fallback.to_string()
        } else {
            value.to_string()
        }
    };
    (
        pick("TFSTATE_ACCESS_KEY", &derived.scw_access_key),
        pick("TFSTATE_SECRET_KEY", &derived.scw_secret_key),
        pick("TFSTATE_REGION", &derived.scw_region),
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::test_support::resolved;

    #[test]
    fn extracts_and_lowercases_provider_names() {
        let r = resolved(&[
            ("PROVIDER_TENSORX_API_KEY_STAGING", "tensorx-key"),
            ("PROVIDER_MISTRAL_API_KEY_STAGING", "mistral-key"),
        ]);
        let keys = provider_api_keys(&r, Env::Staging);
        assert_eq!(keys.get("tensorx").map(String::as_str), Some("tensorx-key"));
        assert_eq!(keys.get("mistral").map(String::as_str), Some("mistral-key"));
        assert_eq!(keys.len(), 2);
    }

    #[test]
    fn ignores_other_environments_and_non_provider_keys() {
        let r = resolved(&[
            ("PROVIDER_TENSORX_API_KEY_STAGING", "stg"),
            ("PROVIDER_TENSORX_API_KEY_PRODUCTION", "prod"),
            ("STAAN_API_KEY_STAGING", "staan"),
        ]);
        let keys = provider_api_keys(&r, Env::Staging);
        assert_eq!(keys.get("tensorx").map(String::as_str), Some("stg"));
        assert_eq!(keys.len(), 1);
    }

    #[test]
    fn backend_creds_prefer_dot_env_per_field() {
        let derived = Derived {
            scw_secret_key: "scw-secret".into(),
            scw_access_key: "scw-access".into(),
            scw_region: "fr-par".into(),
            image_tag: "abc123".into(),
        };
        let r = resolved(&[("TFSTATE_ACCESS_KEY", "scoped-access")]);
        assert_eq!(
            backend_creds(&r, &derived),
            (
                "scoped-access".to_string(),
                "scw-secret".to_string(),
                "fr-par".to_string()
            )
        );
    }
}
